const tasks = $input.all().map(i=>i.json);
const today = new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'});
const emojis = {Vespera:'🖤',Kemuni:'🚀','Mission Control':'🧠',Infrastructure:'⚙️'};
const byProj = {};
for (const t of tasks) {
  if (!byProj[t.project]) byProj[t.project] = [];
  byProj[t.project].push(t);
}
let lines = [`📋 **Sprint Scope — ${today}**\n`];
for (const [proj, pts] of Object.entries(byProj)) {
  const shown = pts.filter(t => t.priority === 'critical' || t.priority === 'high').slice(0,4);
  if (!shown.length) continue;
  lines.push(`${emojis[proj]||'📌'} **${proj}**`);
  for (const t of shown) {
    const badge = t.priority === 'critical' ? '🔴' : '🟠';
    lines.push(`  ${badge} ${t.title.slice(0,55)}`);
  }
  lines.push('');
}
lines.push('_Reply LGTM to confirm, or suggest changes._');
return [{json:{content: lines.join('\n')}}];

